// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Garage.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");
}


