// Input = Shelly 25 Eingang (mech. Schalter zu)
// es gibt nur 1 Schalter = geschlossen
// Switch = Shelly 25 Kontakt (1s)
// 1) Torantriebe - geschlossen
on({ id: 'shelly.0.SHSW-25#483FDA8241A8#1.Relay0.Input' /* Input / Detach */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') == true) {
    setState('javascript.0.Garage.Garage_Zoe_Status', 0, true);
    console.debug('Garage - Tor Zoe ist geschlossen');
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Tor Zoe ist geschlossen');
    if (getState('javascript.0.Garage.Zoe_Status').val == 3) {
      setState('javascript.0.Garage.Zoe_Status', 0, true);
      console.debug('Garage - Zoe steht in der Garage');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Zoe steht in der Garage');
    }
  }
});
