// 2) Torantrieb - öffnet/schließt
// Zoe
on({ id: [].concat(['shelly.0.SHPLG-S#EED8F9#1.Relay0.Power']).concat(['shelly.0.SHSW-25#483FDA8241A8#1.Relay0.Switch']), change: 'ne' }, async (obj) => {
  if (getState('javascript.0.Garage.Tor_Zoe_aktiv').val == false) {
    if (getState('shelly.0.SHSW-25#483FDA8241A8#1.Relay0.Switch').val == true || getState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Power').val >= 10) {
      setState('javascript.0.Garage.Tor_Zoe_aktiv', true);
      setStateDelayed('javascript.0.Garage.Tor_Zoe_aktiv', false, 30000, false);
      setState('javascript.0.Garage.Tor_Zoe_Verzögerung', true);
      setStateDelayed('javascript.0.Garage.Tor_Zoe_Verzögerung', false, 900000, false);
    }
  }
});
on({ id: [].concat(['javascript.0.Garage.Tor_Zoe_aktiv']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('javascript.0.Garage.Tor_Zoe_aktiv').val == true) {
    console.debug('Garage - Antrieb Zoe aktiviert');
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Antrieb Zoe aktiviert');
    (() => { if (timeout_Zoe) { clearTimeout(timeout_Zoe); timeout_Zoe = null; }})();
    if (getState('javascript.0.Garage.Garage_Zoe_Status').val == 0) {
      setState('javascript.0.Garage.Garage_Zoe_Status', 1, true);
      console.debug('Garage - Tor Zoe öffnet');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Tor Zoe öffnet');
      timeout_Zoe = setTimeout(async () => {
        timeout_Zoe = null;
        setState('javascript.0.Garage.Garage_Zoe_Status', 2, true);
        console.debug('Garage - Tor Zoe ist offen');
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Tor Zoe ist offen');
        if (getState('javascript.0.Garage.Zoe_Status').val == 0) {
          setState('javascript.0.Garage.Zoe_Status', 1, true);
          console.debug('Garage - Zoe vorr. unterwegs');
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Zoe vorr. unterwegs');
          timeout_zoe_verlassen = setTimeout(async () => {
            timeout_zoe_verlassen = null;
            if (getState('javascript.0.Garage.Zoe_Status').val == 1) {
              setState('javascript.0.Garage.Zoe_Status', 0, true);
              console.debug('Garage - Zoe vorr. unterwegs wieder gelöscht');
              await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Zoe vorr. unterwegs wieder gelöscht');
            }
          }, 900000);
        } else if (getState('javascript.0.Garage.Zoe_Status').val == 2) {
          setState('javascript.0.Garage.Zoe_Status', 3, true);
          console.debug('Garage - Zoe vorr. wieder zu Hause');
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Zoe vorr. wieder zu Hause');
        }
      }, 20000);
    } else if (getState('javascript.0.Garage.Garage_Zoe_Status').val == 2) {
      setState('javascript.0.Garage.Garage_Zoe_Status', 3, true);
      console.debug('Garage - Tor Zoe schließt');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Tor Zoe schließt');
    } else {
      setState('javascript.0.Garage.Garage_Zoe_Status', 4, true);
      console.debug('Garage - Tor Zoe ist undefiniert');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Tor Zoe ist undefiniert');
    }
  } else {
    if (getState('javascript.0.Garage.Garage_Zoe_Status').val == 1 && getState('javascript.0.Garage.Garage_Zoe_Status').val == 3) {
      setState('javascript.0.Garage.Garage_Zoe_Status', 4, true);
      console.debug('Garage - Tor Zoe ist undefiniert');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Garage - Tor Zoe ist undefiniert');
    }
  }
});
